  StudySumTopic('lgs_tr.s5', 'lgs_tr', 'Paragraf', [
    ['Paragrafın yapısı', 'Paragraf giriş (konu tanıtımı), gelişme (düşüncenin açılması) ve sonuç (düşüncenin bağlanması) bölümlerinden oluşur.'],
    ['Ana düşünce', 'Yazarın okuyucuya vermek istediği temel mesajdır. Genellikle sonuç cümlesinde ya da paragrafın ilk ya da son cümlesinde yer alır. "Bu paragrafın ana düşüncesi nedir?" sorusunda aranır.'],
    ['Konu', 'Paragrafın üzerinde durduğu şeydir; "Bu paragraf neyi anlatıyor?" sorusunun cevabıdır. Konu bir sözcük ya da kısa bir sözcük grubuyla belirtilir.'],
    ['Yardımcı düşünce', 'Ana düşünceyi destekleyen, açıklayan düşünce cümleleridir. Ana düşünce yardımcı düşüncelerle kuvvetlenir.'],
    ['Düşünceyi geliştirme yolları', 'Tanımlama, karşılaştırma, örneklendirme, tanık gösterme, sayısal verilerden yararlanma, benzetme, ilişki kurma, tanımlama, neden-sonuç ilişkisi.'],
    ['Paragrafta anlatım biçimleri', 'Betimleme (anlatma ile görme), öyküleme (olay anlatımı), açıklama (bilgi verme), tartışma (düşünce savunma).'],
    ['Paragrafı tamamlama / cümle çıkarma', 'Boşluğa gelecek cümle, paragrafın akışını bozmamalıdır. Cümleyi çıkarma sorusunda paragrafın bütünündeki anlam akışına uymayan cümle bulunur.'],
    ['Paragraf soru ipucu', 'Önce soru kökünü oku, sonra paragrafı oku, çelişen ve abartılı seçeneklerden kaçın. "Yalnız", "mutlaka", "hiçbir zaman" gibi kesin ifadeli seçenekler genelde yanlıştır.'],
  ], grp: 'Paragraf soruları ve okuma'),
  StudySumTopic('lgs_tr.s14', 'lgs_tr', 'Paragraf soru kalıpları', [
    ['Ana düşünce soruları', '"Bu parçanın ana düşüncesi nedir?", "Yazar neyi savunmaktadır?", "Parçadan çıkarılabilecek en kapsamlı yargı hangisidir?" İpucu: Paragrafın başında ya da sonunda öğüt veya yargı cümlesi ara.'],
    ['Konu soruları', '"Bu parçada asıl anlatılmak istenen nedir?", "Parçanın konusu hangisidir?" İpucu: Konu bir ad ya da kısa ad grubudur; yargı içermez.'],
    ['Başlık soruları', '"Bu parçaya hangi başlık uygun olur?" İpucu: Başlık hem konuyu hem ana düşünceyi karşılamalı, çok genel ya da çok dar olmamalı.'],
    ['Yardımcı düşünce soruları', '"Yazarın ana düşünceyi desteklemek için kullandığı yol nedir?", "Aşağıdakilerden hangisi parçadaki yardımcı düşüncedir?"'],
    ['Çıkarım soruları', '"Parçadan hangisine ulaşılamaz?", "Bu parçaya göre aşağıdakilerden hangisi söylenemez?" İpucu: Seçenekleri metinle tek tek karşılaştır; yazılmayanı kabul etme.'],
    ['Anlatım biçimi soruları', '"Parçada aşağıdakilerden hangisi kullanılmıştır?" Tanımlama, örnekleme, karşılaştırma, benzetme gibi yolları ara.'],
    ['Anlatıcı ve bakış açısı', '"Bu parçada anlatıcı kimdir?" Birinci kişi: ben; üçüncü kişi: o. Kahraman anlatıcı ya da gözlemci anlatıcı.'],
    ['Cümle sırası soruları', '"Numaralanmış cümleler anlamlı bir bütün oluşturmak için nasıl sıralanmalıdır?" İpucu: Önce giriş cümlesini, sonra bağlaç ve zamir ipuçlarını bul.'],
    ['Cümle çıkarma / ekleme soruları', '"Hangi cümle anlam bütünlüğünü bozar?" İpucu: Konudan sapan ya da farklı bir düşünce içeren cümle çıkar.'],
    ['Paragrafı tamamlama soruları', 'Boşluğa gelecek cümlenin öncesiyle ve sonrasıyla mantıklı bağ kurması gerekir.'],
    ['Genel strateji', 'Önce soru kökünü oku. Parçayı bir kez dikkatle oku. Seçenekleri tek tek metinle karşılaştır. "Her zaman, hiçbir zaman, yalnızca" kesin ifadelerine dikkat et.'],
  ], grp: 'Paragraf soruları ve okuma'),
  StudySumTopic('lgs_tr.s15', 'lgs_tr', 'Okuma 1: Okumanın gücü', [
    ['Parça', 'Kitap okumak, insanın dünyasını sessizce genişleten bir yolculuktur. Her sayfada yeni bir kelime, yeni bir düşünce ve yeni bir bakış açısı buluruz. Okuyan kişi, hiç gitmediği yerleri görür, hiç tanımadığı insanların duygularını anlar. Üstelik okumak, yalnızca bilgi kazandırmaz; düşünme becerisini de geliştirir. Bu yüzden çok okuyan insanlar kendilerini daha doğru ifade eder ve sorunlara farklı açılardan bakabilir. Okumayı alışkanlık hâline getirmek için her gün birkaç sayfa yeterlidir.'],
    ['Konu', 'Bu parçanın konusu nedir? || Okumanın faydaları'],
    ['Ana düşünce', 'Bu parçanın ana düşüncesi nedir? || Okumak, insanın hem bilgisini hem de düşünme becerisini geliştirir.'],
    ['Yardımcı düşünce', 'Ana düşünceyi destekleyen düşünce hangisidir? || Okuyan kişi farklı yerleri ve insanları tanır; kendini daha doğru ifade eder.'],
    ['Anlatım', 'Parçada hangi anlatım biçimi ve düşünceyi geliştirme yolu vardır? || Açıklama (bilgi verme); örnekleme ve neden-sonuç yolu kullanılmıştır.'],
  ], grp: 'Paragraf soruları ve okuma'),
  StudySumTopic('lgs_tr.s16', 'lgs_tr', 'Okuma 2: Su ve hayat', [
    ['Parça', 'Dünyanın dörtte üçü sudur; ama içilebilir tatlı su bunun yalnızca çok küçük bir bölümüdür. Bir damla suyun nasıl bir emek ve zaman sonunda musluğumuza geldiğini çoğumuz düşünmeyiz. Dişlerimizi fırçalarken musluğu açık bırakmak, günde yüzlerce litre suyun boşa gitmesine neden olabilir. Oysa küçük tedbirlerle büyük tasarruf sağlanır. Unutmayalım ki su tükenirse hayat da tükenir. Bu nedenle suyu tasarruflu kullanmak, hepimizin ortak sorumluluğudur.'],
    ['Konu', 'Bu parçanın konusu nedir? || Suyun önemi ve tasarrufu'],
    ['Ana düşünce', 'Bu parçanın ana düşüncesi nedir? || Su sınırlı bir kaynaktır; bu yüzden tasarruflu kullanılmalıdır.'],
    ['Yardımcı düşünce', 'Ana düşünceyi destekleyen düşünce hangisidir? || Tatlı su çok azdır ve küçük tedbirlerle büyük tasarruf sağlanır.'],
    ['Anlatım', 'Parçada hangi anlatım biçimi ve düşünceyi geliştirme yolu vardır? || Tartışma ve açıklama; sayısal veri (dörtte üç) kullanılmıştır.'],
  ], grp: 'Paragraf soruları ve okuma'),
  StudySumTopic('lgs_tr.s17', 'lgs_tr', 'Okuma 3: Çocukluk sokağı', [
    ['Parça', 'Çocukluğumun geçtiği sokak dar ve taş döşeliydi. Sabahları fırından yayılan sıcak ekmek kokusu bütün evlere dolardı. Komşular pencerelerden birbirlerine seslenir, çocuklar bahçe kapılarının önünde misket oynardı. Akşam olunca anneler, ellerindeki kepçeleri sallayarak adımızı bağırırdı. O sokağa yıllar sonra tekrar gittiğimde taşlar hâlâ yerindeydi; ama ne kokular ne sesler vardı. Sanki zaman, bütün neşeyi bir bohçaya sarıp götürmüştü.'],
    ['Konu', 'Bu parçanın konusu nedir? || Çocukluk anıları ve sokak'],
    ['Ana düşünce', 'Bu parçanın ana düşüncesi nedir? || Zamanla birlikte geçmişin sıcak ve neşeli ortamı kaybolur.'],
    ['Yardımcı düşünce', 'Ana düşünceyi destekleyen düşünce hangisidir? || Sokaktaki koku, ses ve oyunlar anlatılarak eski günlerin özlemi vurgulanır.'],
    ['Anlatım', 'Parçada hangi anlatım biçimi ve düşünceyi geliştirme yolu vardır? || Betimleme ve öyküleme; kişileştirme (zaman bohça sarıp götürmüş) kullanılmıştır.'],
  ], grp: 'Paragraf soruları ve okuma'),
  StudySumTopic('lgs_tr.s18', 'lgs_tr', 'Okuma 4: Teknoloji ve dikkat', [
    ['Parça', 'Telefonlar artık hayatımızın merkezinde. Yemek yerken, yürürken, hatta arkadaşlarımızla otururken bile ekrana bakıyoruz. Araştırmalar, sık bildirim alan kişilerin dikkatini toplamakta zorlandığını gösteriyor. Üstelik sürekli ekranda geçirilen zaman, uykuyu ve yüz yüze iletişimi azaltıyor. Teknoloji kötü değildir; asıl sorun, onu ne kadar ve nasıl kullandığımızdır. Telefonu bırakıp bir süre doğaya çıkmak, zihni dinlendirmenin en kolay yoludur.'],
    ['Konu', 'Bu parçanın konusu nedir? || Teknolojinin kullanımı'],
